+<!DOCTYPE html>
+<html lang="ru">
+
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
+    <title>Инструкция - Makita LXT Light</title>
+    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css">
+    <style>
+        :root {
+            --primary-color: #2c3e50;
+            --secondary-color: #34495e;
+            --accent-color: #27ae60;
+            --text-color: #333;
+            --warning-color: #ff9800;
+            --note-color: #3498db;
+            --error-color: #e74c3c;
+            --success-color: #2ecc71;
+        }
+
+        * {
+            box-sizing: border-box;
+        }
+
+        body {
+            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+            margin: 0;
+            padding: 0;
+            background-color: #f5f5f5;
+            color: var(--text-color);
+            line-height: 1.6;
+        }
+
+        .content {
+            padding: 25px;
+            max-width: 1200px;
+            margin: 0 auto;
+        }
+
+        .section {
+            margin-bottom: 35px;
+            padding: 25px;
+            background-color: white;
+            border-radius: 8px;
+            box-shadow: 0 2px 15px rgba(0, 0, 0, 0.05);
+        }
+
+        h1 {
+            color: var(--primary-color);
+            border-bottom: 2px solid var(--accent-color);
+            padding-bottom: 15px;
+            margin-bottom: 25px;
+            font-size: 2rem;
+        }
+
+        h2 {
+            color: var(--primary-color);
+            font-size: 1.6rem;
+            margin-bottom: 20px;
+            display: flex;
+            align-items: center;
+        }
+
+        h2 i {
+            margin-right: 10px;
+            color: var(--accent-color);
+        }
+
+        h3 {
+            color: var(--primary-color);
+            font-size: 1.3rem;
+            margin-bottom: 15px;
+            display: flex;
+            align-items: center;
+        }
+
+        h3 i {
+            margin-right: 10px;
+            color: var(--accent-color);
+            font-size: 0.9em;
+        }
+
+        .image-container {
+            text-align: center;
+            margin: 25px 0;
+            border: 1px solid #e0e0e0;
+            border-radius: 8px;
+            padding: 15px;
+            background-color: #fafafa;
+        }
+
+        .image-container img {
+            max-width: 50%;
+            height: auto;
+            border-radius: 5px;
+            cursor: pointer;
+            transition: transform 0.3s ease;
+        }
+
+        .image-container img:hover {
+            transform: scale(1.05);
+        }
+
+        .image-caption {
+            font-style: italic;
+            color: #666;
+            margin-top: 10px;
+            font-size: 0.9rem;
+        }
+
+        .note {
+            background-color: rgba(52, 152, 219, 0.1);
+            border-left: 4px solid var(--note-color);
+            padding: 15px;
+            margin: 25px 0;
+            border-radius: 0 6px 6px 0;
+        }
+
+        .note i {
+            color: var(--note-color);
+            margin-right: 8px;
+        }
+
+        .warning {
+            background-color: rgba(255, 152, 0, 0.1);
+            border-left: 4px solid var(--warning-color);
+            padding: 15px;
+            margin: 25px 0;
+            border-radius: 0 6px 6px 0;
+        }
+
+        .warning i {
+            color: var(--warning-color);
+            margin-right: 8px;
+        }
+
+        .error {
+            background-color: rgba(231, 76, 60, 0.1);
+            border-left: 4px solid var(--error-color);
+            padding: 15px;
+            margin: 25px 0;
+            border-radius: 0 6px 6px 0;
+        }
+
+        .error i {
+            color: var(--error-color);
+            margin-right: 8px;
+        }
+
+        ol, ul {
+            padding-left: 25px;
+            line-height: 1.6;
+        }
+
+        li {
+            margin-bottom: 10px;
+        }
+
+        p {
+            line-height: 1.6;
+            margin-bottom: 15px;
+        }
+
+        strong {
+            color: var(--primary-color);
+        }
+
+        .light-badge {
+            background-color: #27ae60;
+            color: white;
+            padding: 3px 10px;
+            border-radius: 4px;
+            font-size: 0.8rem;
+            font-weight: bold;
+            margin-left: 10px;
+        }
+
+        .back-link {
+            display: inline-block;
+            margin-top: 30px;
+            padding: 12px 25px;
+            background-color: var(--accent-color);
+            color: white;
+            text-decoration: none;
+            border-radius: 5px;
+            font-weight: 600;
+            transition: all 0.3s ease;
+        }
+
+        .back-link:hover {
+            background-color: #229954;
+            transform: translateY(-2px);
+        }
+
+        .modal {
+            display: none;
+            position: fixed;
+            z-index: 1000;
+            left: 0;
+            top: 0;
+            width: 100%;
+            height: 100%;
+            background-color: rgba(0, 0, 0, 0.9);
+        }
+
+        .modal-content {
+            display: block;
+            margin: auto;
+            max-width: 90%;
+            max-height: 90%;
+            position: absolute;
+            top: 50%;
+            left: 50%;
+            transform: translate(-50%, -50%);
+            border-radius: 8px;
+        }
+
+        .close {
+            position: absolute;
+            top: 20px;
+            right: 35px;
+            color: #fff;
+            font-size: 40px;
+            font-weight: bold;
+            cursor: pointer;
+        }
+
+        @media screen and (max-width: 768px) {
+            .content {
+                padding: 20px 15px;
+            }
+
+            h1 {
+                font-size: 1.6rem;
+            }
+
+            h2 {
+                font-size: 1.4rem;
+            }
+
+            .image-container img {
+                max-width: 100%;
+            }
+        }
+    </style>
+</head>
+
+<body>
+    <div class="content">
+        <h1><i class="fas fa-battery-half"></i> Диагностика аккумуляторов c Light version <span class="light-badge">LIGHT</span></h1>
+        
+        <div class="note">
+            <p><i class="fas fa-info-circle"></i> <strong>Light версия</strong> - упрощенная версия диагностического модуля без встроенного аккумулятора.</p>
+        </div>
+
+        <div class="section" id="section1">
+            <h2><i class="fas fa-info-circle"></i> 1. Особенности Light версии</h2>
+            <p>Light версия диагностического модуля отличается от стандартной версии следующими особенностями:</p>
+            
+            <ul>
+                <li><strong>Отсутствие встроенного аккумулятора</strong> - устройство питается от внешнего источника (телефон или другой источник) питания через USB кабель</li>
+                <li><strong>Компактный размер</strong> - меньшие габариты и вес</li>
+                <li><strong>Полный функционал диагностики</strong> - все возможности чтения данных и управления сохранены</li>
+            </ul>
+
+            <div class="image-container">
+                <img src="images/nemakita light.png" alt="Диагностический модуль LXT Light">
+                <div class="image-caption">Рис. 1.1 - Диагностический модуль LXT Light</div>
+            </div>
+
+            <div class="warning">
+                <p><i class="fas fa-exclamation-triangle"></i> <strong>Важно!</strong> Для работы устройства необходимо подать питание через USB порт.</p>
+            </div>
+        </div>
+
+        <div class="section" id="section2">
+            <h2><i class="fas fa-plug"></i> 2. Питание устройства</h2>
+            
+            <h3><i class="fas fa-usb"></i> 2.1. Питание через USB</h3>
+            <p>Питание устройства осуществляется через USB кабель:</p>
+
+            <ol>
+                <li>Подключите USB кабель к порту питания на устройстве</li>
+                <li>Подключите второй конец к источнику питания (5V, минимум 500 mA) или к телефону.</li>
+                <li>Если подключили к телефону, в всплывающем окне выберите "Передача файла" чтобы пошло питание на прибор.</li>
+            </ol>
+
+            <div class="image-container">
+                <img src="images/nemakita light usb.png" alt="Питание через USB">
+                <div class="image-caption">Рис. 2.1 - Подключение USB питания</div>
+            </div>
+
+            <div class="warning">
+                <p><i class="fas fa-exclamation-triangle"></i> <strong>Внимание!</strong></p>
+                <ul>
+                    <li>Используйте только качественные USB кабели и зарядные устройства</li>
+                    <li>Минимальные требования: 5V, 500 mA</li>
+                    <li>Не используйте кабели с поврежденной изоляцией</li>
+                </ul>
+            </div>
+        </div>
+
+        <div class="section" id="section3">
+            <h2><i class="fas fa-wifi"></i> 3. Подключение через NFC</h2>
+            
+            <h3><i class="fas fa-mobile-alt"></i> 3.1. Использование NFC метки</h3>
+            <p>Для быстрого подключения к точке доступа Wi-Fi устройства используйте NFC метку:</p>
+
+            <ol>
+                <li>Включите NFC на вашем смартфоне</li>
+                <li>Поднесите смартфон к NFC метке на устройстве</li>
+                <li>Нажмите на уведомление о подключении к сети Wi-Fi</li>
+                <li>Дождитесь подключения к точке доступа "Makita"</li>
+                <li>Captive portal откроется автоматически</li>
+                <li>Если Captive portal не откроется автоматически, перейдите в браузере по адресу <strong>http://192.168.4.1</strong></li>
+            </ol>
+
+            <div class="image-container">
+                <img src="images/nemakita light nfc.png" alt="Подключение через NFC">
+                <div class="image-caption">Рис. 3.1 - Подключение смартфона через NFC метку</div>
+            </div>
+
+            <div class="note">
+                <p><i class="fas fa-info-circle"></i> <strong>Если NFC не сработал:</strong></p>
+                <ul>
+                    <li>Убедитесь, что NFC включен на вашем смартфоне</li>
+                    <li>Поднесите смартфон ближе к метке (расстояние 1-2 см)</li>
+                    <li>Попробуйте поднести смартфон другой стороной</li>
+                </ul>
+            </div>
+
+            <h3><i class="fas fa-wifi"></i> 3.2. Ручное подключение к Wi-Fi</h3>
+            <p>Если NFC подключение недоступно, подключитесь вручную:</p>
+
+            <div class="note">
+                <p><i class="fas fa-info-circle"></i> <strong>SSID:</strong> Makita</p>
+                <p><strong>Пароль:</strong> 12345678</p>
+                <p><strong>IP-адрес:</strong> 192.168.4.1</p>
+            </div>
+
+            <ol>
+                <li>Откройте настройки Wi-Fi на вашем устройстве</li>
+                <li>Найдите сеть "Makita" и подключитесь к ней</li>
+                <li>Введите пароль: <strong>12345678</strong></li>
+                <li>Откройте браузер и перейдите по адресу <strong>http://192.168.4.1</strong></li>
+            </ol>
+        </div>
+
+        <a href="index.html" class="back-link">
+            <i class="fas fa-arrow-left"></i> Вернуться к главной странице
+        </a>
+    </div>
+
+    <!-- Модальное окно для изображений -->
+    <div id="imageModal" class="modal">
+        <span class="close">&times;</span>
+        <img class="modal-content" id="modalImage">
+    </div>
+
+    <script>
+        document.addEventListener('DOMContentLoaded', function() {
+            // Модальное окно для изображений
+            const modal = document.getElementById('imageModal');
+            const modalImg = document.getElementById('modalImage');
+            const closeBtn = document.getElementsByClassName('close')[0];
+
+            document.querySelectorAll('.image-container img').forEach(img => {
+                img.addEventListener('click', function() {
+                    modal.style.display = 'block';
+                    modalImg.src = this.src;
+                });
+            });
+
+            if (closeBtn) {
+                closeBtn.onclick = function() {
+                    modal.style.display = 'none';
+                }
+            }
+
+            window.onclick = function(event) {
+                if (event.target === modal) {
+                    modal.style.display = 'none';
+                }
+            }
+        });
+    </script>
+</body>
+
+</html>

